  parab = parab--(y^2/4,y);
}

draw(parab,red);
draw((-2,0)--(16,0));
draw((0,-8)--(0,8));
draw(Circle(O,r));
draw(A--B);

dot("$A$", A, N);
dot("$B$", B, W);
